import path from 'node:path'

/**
 * Converts a git branch name to a safe filename by replacing all forward-slash
 * characters with dashes and appending the `.txt` extension.
 */
export function branchToFilename (branch: string): string {
  return `${branch.replace(/\//g, '-')}.txt`
}

/**
 * Reads all `.txt` files in the given directory and collects their non-empty,
 * non-comment lines as changeset IDs. Returns an empty Set if the directory
 * does not exist.
 */
export function readReleased (dir: string): Set<string> {
  const ids = new Set<string>()
  let entries: string[]
  try {
    entries = fs.readdirSync(dir)
  } catch {
    return ids
  }
  for (const entry of entries) {
    if (!entry.endsWith('.txt')) continue
    const content = fs.readFileSync(path.join(dir, entry), 'utf8')
    for (const line of content.split('\n')) {
      const id = line.trim()
      if (id === '' || id.startsWith('#')) continue
      ids.add(id)
    }
  }
  return ids
}

/**
 * Appends the given list of changeset IDs to the file corresponding to
 * `branchToFilename(branch)` inside `dir`, deduplicating against IDs already
 * present in that file and writing the merged, sorted list back (one ID per
 * line, with a trailing newline). Creates `dir` (and parents) if needed. Is a
 * no-op if `ids` is empty.
 */
export function appendReleased (dir: string, branch: string, ids: string[]): void {
  if (ids.length === 0) return
  fs.mkdirSync(dir, { recursive: true })
  const filePath = path.join(dir, branchToFilename(branch))
  const merged = new Set<string>()
  try {
    const content = fs.readFileSync(filePath, 'utf8')
    for (const line of content.split('\n')) {
      const id = line.trim()
      if (id === '' || id.startsWith('#')) continue
      merged.add(id)
    }
  } catch {
    // File does not exist yet; start from an empty set.
  }
  for (const id of ids) {
    merged.add(id)
  }
  const sorted = Array.from(merged).sort()
  fs.writeFileSync(filePath, `${sorted.join('\n')}\n`)
}

export interface HiddenChangeset {
  id: string
  from: string
  to: string
  [key: string]: unknown
}

/**
 * For each `.md` file in `dir` whose basename (without `.md`) is contained in
 * `releasedIds`, renames the file from `<id>.md` to `<id>.md.released`. If any
 * rename fails mid-way, all completed renames are rolled back and the original
 * error is re-thrown.
 */
export function hideReleased (dir: string, releasedIds: Set<string>): HiddenChangeset[] {
  const hidden: HiddenChangeset[] = []
  try {
    for (const id of releasedIds) {
      const from = path.join(dir, `${id}.md`)
      if (!fs.existsSync(from)) continue
      const to = `${from}.released`
      fs.renameSync(from, to)
      hidden.push({ id, from, to })
    }
  } catch (err) {
    for (const entry of hidden) {
      fs.renameSync(entry.to, entry.from)
    }
    throw err
  }
  return hidden
}

/**
 * Renames each `.md.released` file referenced in the `hidden` array back to its
 * original `.md` filename.
 */
export function restoreHidden (hidden: HiddenChangeset[]): void {
  for (const entry of hidden) {
    fs.renameSync(entry.to, entry.from)
  }
}

/**
 * Permanently deletes each `.md.released` file referenced in the `hidden`
 * array.
 */
export function deleteHidden (hidden: HiddenChangeset[]): void {
  for (const entry of hidden) {
    fs.rmSync(entry.to, { force: true })
  }
}

/**
 * Returns a sorted array of changeset IDs by listing `.md` files in `dir`,
 * stripping the `.md` extension and excluding `README.md`.
 */
export function listChangesetIds (dir: string): string[] {
  return fs.readdirSync(dir)
    .filter((entry) => entry.endsWith('.md') && entry !== 'README.md')
    .map((entry) => entry.slice(0, -'.md'.length))
    .sort()
}
